export const mlGiris: { q: string; a: string }[] = [
  { q: 'Bu başlık ne öğretir?', a: 'Kendi verinle kendi modelini eğitmeyi. Buraya kadar hazır dil modellerini kullandık; şimdi tablo halindeki veriden (Excel gibi satır ve sütunlar) tahmin yapan küçük modeller kuracağız: ev fiyatı tahmini, hangi müşterinin ayrılacağı, bir e-postanın spam olup olmadığı, müşterileri gruplara ayırma. Araç Python\'un scikit-learn kütüphanesi.' },
  { q: 'Makine öğrenmesi tam olarak ne yapıyor?', a: 'Geçmiş örneklerden kural çıkarıyor. Bin evin metrekaresini, oda sayısını ve satış fiyatını verirsin; model "metrekare arttıkça fiyat şu kadar artar" gibi ilişkileri sayılarla öğrenir. Sonra yeni bir evin özelliklerini verince fiyat tahmini yapar. Kuralı sen yazmazsın, veriden çıkar. Temeller bölümünde anlattığımız her şey burada kodla hayata geçer.' },
  { q: 'ChatGPT varken neden bununla uğraşayım?', a: 'Sayısal tablo veride klasik makine öğrenmesi hem daha doğru hem bin kat ucuz hem milisaniyede çalışır hem de nedenini açıklayabilir. Bir bankanın milyonlarca işlemi için dil modeli çağırmak hem yavaş hem pahalıdır; küçük bir boosting modeli saniyede binlerce tahmin yapar. Dil modeli metin için, klasik makine öğrenmesi sayılar için.' },
  { q: 'scikit-learn nedir?', a: 'Python\'un standart makine öğrenmesi kütüphanesi. Onlarca algoritmayı aynı üç komutla kullandırır: modeli oluştur, fit ile öğret, predict ile tahmin et. Veri hazırlama, değerlendirme ve boru hattı (pipeline) araçları da içinde. Ücretsiz, iyi belgelenmiş, yirmi yıldır endüstri standardı.' },
  { q: 'fit ve predict ne demek?', a: 'fit: "bu örneklerden öğren" komutu; modele özellikleri ve doğru cevapları verirsin, içindeki sayıları ayarlar. predict: "bu yeni örnek için tahmin et" komutu; sadece özellikleri verirsin, cevabı o üretir. scikit-learn\'deki her model bu iki komutla çalışır; birini öğrenince hepsini öğrenmiş olursun.' },
  { q: 'Ne kadar veri gerekir?', a: 'Basit problemde yüzlerce satır, çoğu iş probleminde binlerce. Daha az veride basit model seçer ve çapraz doğrulama ile dikkatli ölçersin. Verinin miktarından çok kalitesi önemli: temiz, doğru etiketli ve gerçek kullanımı yansıtan bin satır, kirli yüz bin satırdan iyidir.' },
  { q: 'Matematik gerekiyor mu?', a: 'Fikir düzeyinde: ortalama, yüzde, "hata ne kadar" kavramları yeter. Hesapları kütüphane yapar. Formülleri bilmeden de iyi model kurabilirsin; neyin neden çalıştığını anlamak istersen Temeller bölümündeki kayıp fonksiyonu ve gradyan konuları yeterli sezgiyi verir.' },
  { q: 'Hangi algoritmayı seçmeliyim?', a: 'Tablo veride neredeyse her zaman önce gradient boosting (LightGBM, XGBoost) ve random forest dene; en iyi sonucu genelde bunlar verir. Nedenini açıklaman gerekiyorsa doğrusal modeller. Önce en basit modeli (baseline) kur, sonra güçlüyü dene ve farkı ölç. Tahmin değil ölçüm karar verir.' },
  { q: 'Tipik iş akışı nasıl?', a: 'Veriyi yükle, keşfet, temizle, yeni özellikler üret, eğitim ve test olarak böl, modeli eğit, test verisinde ölç, ayarları iyileştir, kaydet, servise koy. Zamanın çoğu ilk dört adımda (veriyle) geçer; model eğitmek genelde en kısa kısımdır.' },
  { q: 'En sık yapılan hata ne?', a: 'Test verisinin eğitime sızması: ölçekleyiciyi tüm veride ayarlayıp sonra bölmek, ya da gelecekte öğrenilecek bir bilgiyi özellik yapmak. Sonuç laboratuvarda mükemmel, gerçekte kötü model. Bu bölüm pipeline kavramıyla bu hatayı yapısal olarak önlemeyi öğretir.' },
  { q: 'Ön koşul ne?', a: 'Python temel düzey, Pandas (tablo veriyi okumak ve düzenlemek; Veri grubunda ayrı başlık) ve Yapay Zeka Temelleri\'ndeki kavramlar: özellik, etiket, eğitim-test, overfitting, değerlendirme ölçütleri. Bunları bilmeden kodlar çalışır ama ne yaptığını anlamazsın.' },
  { q: 'Derin öğrenmeden farkı ne?', a: 'Derin öğrenme (sinir ağları) görüntü, ses ve metin gibi ham veri için; tablo veride boosting genelde kazanır ve çok daha az kaynak ister. Önce bu başlık, sonra Derin Öğrenme. İkisi birbirinin yerine değil, farklı veri türleri için.' },
  { q: 'Hangi sırayla ilerlemeli?', a: 'Soldaki sıra: İlk Model (on dakikada çalışan örnek) → Önişleme → Pipeline → Regresyon → Sınıflandırma → Model Seçimi → Gözetimsiz → Zaman Serisi → Açıklanabilirlik → Kaydetme ve Servis. İlk üç konu temeli kurar; Regresyon ve Sınıflandırma asıl işi yapar.' },
]

